    "compPropsSnapshot": "src/figma/figma-component-props.snapshot.json",
    "pluginCSS": []
  },
  "states": {
    "hover": {
      "prop": "State",
      "value": "Hover"
    },
    "error": {
      "prop": "State",
      "value": "Error"
    },
    "disabled": {
      "prop": "Disabled"
    }
  }
}

