files.prototypes/notification-settings.json:
{
  "component": "Page",
  "props": {
    "padding": "padding/m",
    "gap": "padding/m",
    "align": "start",
    "width": "360"
  },
  "children": [
    {
      "component": "Text",
      "props": {
        "text": "Notifications",
        "style": "m",
        "as": "h1"
      }
    },
    {
      "component": "Stack",
      "props": {
        "gap": "padding/s",
        "align": "start",
        "name": "Notification channels"
      },
      "children": [
        {
          "id": "email",
          "component": "chip",
          "props": {
            "Label": "Email notifications",
            "Size": "M",
            "Icon": "False",
            "standInFor": "switch"
          }
        },
        {
          "id": "push",
          "component": "chip",
          "props": {
            "Label": "Push notifications",
            "Size": "M",
            "Icon": "False",
            "standInFor": "switch"
          }
        }
      ]
    },
    {
      "id": "confirmation",
      "component": "Missing",
      "props": {
        "need": "confirmation message shown once the settings are saved",
        "kind": "component",
        "closest": "tag"
      }
    },
    {
      "component": "Row",
      "props": {
        "justify": "start"
      },
      "children": [
        {
          "id": "save",
          "component": "button",
          "props": {
            "Label": "Save",
            "Disabled": "False",
            "opens": "confirmation"
          }
        }
      ]
    }
  ],
  "states": {
    "error": {
      "confirmation": {
        "component": "Missing",
        "props": {
          "need": "error message shown when saving fails",
          "kind": "component",
          "closest": "tag"
        }
      }
    }
  }
}

