{
  "component": "Page",
  "props": { "padding": "padding/m", "gap": "padding/m", "width": 360, "align": "stretch" },
  "children": [
    { "component": "Text", "props": { "text": "Sign in", "style": "m", "as": "h1" } },
    { "component": "Stack", "props": { "gap": "padding/s", "stretch": true }, "children": [
      { "component": "Stack", "props": { "gap": "gap/s", "stretch": true }, "children": [
        { "component": "Text", "props": { "text": "Email", "style": "s", "as": "span" } },
        { "id": "email", "component": "field", "props": { "name": "Email", "stretch": true, "standInFor": "an email field (email keyboard, autocomplete)" } }
      ] },
      { "component": "Stack", "props": { "gap": "gap/s", "stretch": true }, "children": [
        { "component": "Text", "props": { "text": "Password", "style": "s", "as": "span" } },
        { "id": "password", "component": "field", "props": { "name": "Password", "stretch": true, "standInFor": "a password field that hides what is typed" } }
      ] },
      { "id": "error", "component": "Missing", "props": { "need": "an error message for a wrong email or password", "kind": "pattern", "closest": "field" } }
    ] },
    { "component": "Row", "props": { "justify": "start" }, "children": [
      { "id": "submit", "component": "button", "props": { "Label": "Sign in", "Disabled": "False" } }
    ] }
  ],
  "states": {
    "default": { "error": null },
    "error": { "error": { "props": { "need": "an error message for a wrong email or password" } } }
  }
}

