    },
    "stepper": {
      "bindings": {}
    }
  }
}

files.prototypes/notes-toolbar.json:
{
  "component": "Page",
  "props": {
    "padding": "padding/m",
    "gap": "padding/m",
    "width": "360"
  },
  "children": [
    {
      "component": "Text",
      "props": {
        "text": "Notes",
        "style": "m",
        "as": "h1"
      }
    },
    {
      "component": "Row",
      "props": {
        "gap": "padding/s",
        "align": "center",
        "wrap": true,
        "name": "Filter notes"
      },
      "children": [
        {
          "component": "chip",
          "id": "filter-all",
          "props": {
            "Size": "M",
            "Icon": "False",
            "Label": "All"
          }
        },
        {
          "component": "chip",
          "id": "filter-mine",
          "props": {
            "Size": "M",
            "Icon": "False",
            "Label": "Mine"
          }
        },
        {
          "component": "chip",
          "id": "filter-shared",
          "props": {
            "Size": "M",
            "Icon": "False",
            "Label": "Shared"
          }
        }
      ]
    },
    {
      "component": "Row",
      "props": {
        "gap": "padding/s",
        "align": "center",
        "stretch": true
      },
      "children": [
        {
          "component": "field",
          "id": "search",
          "props": {
            "standInFor": "search field",
            "name": "Search notes",
            "grow": true
          }
        },
        {
          "component": "chip",
          "id": "pin",
          "props": {
            "Size": "M",
            "Icon": "True",
            "Label": "",
            "name": "Pin note",
            "tip": "Pin note",
            "standInFor": "icon-only toggle to pin the note"
          }
        }
      ]
    },
    {
      "component": "Stack",
      "id": "search-message",
      "props": {
        "gap": "none"
      },
      "children": []
    }
  ],
  "states": {
    "error": {
      "search-message": {
        "component": "Missing",
        "props": {
          "need": "an error look and message for the field (search that cannot run)",
          "kind": "option",
          "closest": "field"
        }
      }
    }
  }
}

files.ds-config.json:
{
  "_note": "Tidepool as a project that has only Figma: no code yet, in build mode. Used by the build evaluation (test/skill-evals). Every name is invented.",
  "figmaFileKey": "b0LpOCBsaRgo8lUqbkQNaY",
  "build": true,
  "maxSnapshotAgeDays": 30,
  "figma": {
    "modes": [
      {
        "name": "Light",
        "snapshotKey": "light",
        "cssSelector": "root"
      },
      {
        "name": "Dark",
        "snapshotKey": "dark",
        "cssSelector": "data:theme=dark"
      }
    ]
  },
  "paths": {
    "themeCSS": [
      "src/styles/tokens.css",
      "src/components/button.css",
      "src/components/chip.css",
      "src/components/disclosure.css",
      "src/components/field.css",
      "src/components/stepper.css",
      "src/components/tag.css"
    ],
    "snapshotVars": "src/figma/figma-vars.snapshot.json",
    "snapshotStructure": "src/figma/figma-structure.snapshot.json",
    "compPropsSnapshot": "src/figma/figma-component-props.snapshot.json",
    "pluginCSS": []
  },
  "states": {
    "hover": {
      "prop": "State",
      "value": "Hover"
    },
    "error": {
      "prop": "State",
      "value": "Error"
    },
    "disabled": {
      "prop": "Disabled"
    }
  }
}

