files.prototypes/project-page.json:
{
  "component": "Page",
  "props": {
    "padding": "padding/m",
    "gap": "padding/m",
    "width": "360"
  },
  "children": [
    {
      "component": "Text",
      "props": {
        "text": "Project",
        "style": "m",
        "as": "h1"
      }
    },
    {
      "component": "Text",
      "props": {
        "text": "Website redesign",
        "style": "s",
        "as": "p"
      }
    },
    {
      "component": "Missing",
      "id": "confirm-delete",
      "props": {
        "need": "a confirmation dialog asking whether to delete the project",
        "kind": "component",
        "closest": "disclosure"
      },
      "children": [
        {
          "component": "Text",
          "props": {
            "text": "Delete this project?",
            "style": "m",
            "as": "h2"
          }
        },
        {
          "component": "Row",
          "props": {
            "gap": "padding/s",
            "justify": "start",
            "wrap": "true"
          },
          "children": [
            {
              "component": "button",
              "props": {
                "Label": "Delete",
                "standInFor": "a destructive action"
              }
            },
            {
              "component": "button",
              "props": {
                "Label": "Cancel",
                "standInFor": "a secondary action"
              }
            }
          ]
        }
      ]
    },
    {
      "component": "Row",
      "props": {
        "justify": "start"
      },
      "children": [
        {
          "component": "button",
          "props": {
            "Label": "Delete project",
            "opens": "confirm-delete"
          }
        }
      ]
    }
  ]
}

